#!/usr/bin/env node
/**
 * Builds the single-file native ESM bundle for Pi SDK Host + precompiled Android extensions:
 *   app/src/main/assets/guest/sdk-host/host.bundle.mjs
 *
 * Why a single-file bundle:
 *  1. Eliminates 26 separate sdk-host `.mjs` module opens/stats under proot/proroot/tawcroot.
 *  2. Pre-compiles the 3 APK-shipped TypeScript extensions (pi-android-bridge,
 *     pi-android-permission-gate, pi-highlight) into native V8 ESM factories passed to
 *     official Pi SDK `DefaultResourceLoader({ extensionFactories })`, completely avoiding
 *     `require("jiti")` + ~1.7 MB `babel.cjs` TypeScript transpilation on every cold boot
 *     while preserving 100% official Pi SDK semantics and full V8 NODE_COMPILE_CACHE coverage.
 *
 * Usage:
 *   node tools/sdk-host/build-bundle.mjs [--esbuild <path-to-esbuild-index>]
 */
import { existsSync, readFileSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, "../..");
const hostDir = join(repo, "app/src/main/assets/guest/sdk-host");
const extDir = join(repo, "app/src/main/assets/pi-extensions");
const outFile = join(hostDir, "host.bundle.mjs");

function findEsbuild() {
  const argIdx = process.argv.indexOf("--esbuild");
  const candidates = [
    argIdx > 0 ? process.argv[argIdx + 1] : null,
    process.env.ESBUILD_PATH,
    join(repo, "node_modules/esbuild/lib/main.js"),
    "/app/applet/node_modules/esbuild/lib/main.js",
  ].filter(Boolean);
  for (const c of candidates) {
    if (existsSync(c)) return c;
  }
  throw new Error(`esbuild not found. Tried: ${candidates.join(", ")}`);
}

const esbuildMod = await import(pathToFileURL(findEsbuild()).href);
const esbuild = esbuildMod.default ?? esbuildMod;

const nodePaths = [
  join(repo, "build/pi-contract/node_modules"),
  join(repo, "node_modules"),
].filter((p) => existsSync(p));

const entrySource = `
import androidBridge from ${JSON.stringify(join(extDir, "pi-android-bridge/index.ts"))};
import permissionGate from ${JSON.stringify(join(extDir, "pi-android-permission-gate.ts"))};
import highlight from ${JSON.stringify(join(extDir, "pi-highlight/index.ts"))};

globalThis.__piAndroidBundledExtensions = {
  androidBridge,
  permissionGate,
  highlight,
};

await import(${JSON.stringify(join(hostDir, "main.mjs"))});
`;

/**
 * Resolves static value imports of `@earendil-works/pi-coding-agent` inside the bundled
 * Android extensions to the exact official SDK instance already loaded by `sdk.mjs`
 * (zero duplicate code, zero fork of official SDK).
 */
const officialSdkBridgePlugin = {
  name: "official-sdk-bridge",
  setup(build) {
    build.onResolve({ filter: /^@earendil-works\/pi-coding-agent$/ }, (args) => {
      if (args.importer && args.importer.includes("pi-extensions")) {
        return { path: "pi-coding-agent-bridge", namespace: "pi-sdk-bridge" };
      }
      return { path: args.path, external: true };
    });
    build.onLoad({ filter: /^pi-coding-agent-bridge$/, namespace: "pi-sdk-bridge" }, () => ({
      contents: `
import { getLoadedSdk } from ${JSON.stringify(join(hostDir, "sdk.mjs"))};
export const DEFAULT_MAX_BYTES = 50 * 1024;
export const DEFAULT_MAX_LINES = 2000;
export const formatSize = (...args) => getLoadedSdk().formatSize(...args);
export const truncateHead = (...args) => getLoadedSdk().truncateHead(...args);
export const truncateTail = (...args) => getLoadedSdk().truncateTail(...args);
`,
      loader: "js",
      resolveDir: hostDir,
    }));
  },
};

await esbuild.build({
  stdin: {
    contents: entrySource,
    resolveDir: hostDir,
    sourcefile: "host-bundle-entry.mjs",
    loader: "js",
  },
  bundle: true,
  format: "esm",
  platform: "node",
  target: "node22",
  minifySyntax: true,
  minifyWhitespace: true,
  minifyIdentifiers: false,
  keepNames: true,
  nodePaths,
  external: [
    "node:*",
    "@earendil-works/pi-coding-agent",
    "@earendil-works/pi-tui",
  ],
  plugins: [officialSdkBridgePlugin],
  banner: {
    js: "// Generated by tools/sdk-host/build-bundle.mjs — do not hand-edit.",
  },
  outfile: outFile,
});

const sz = statSync(outFile).size;
console.log(`Built ${outFile} (${(sz / 1024).toFixed(1)} KB)`);
